/** Пол и потолок опроса за одиннадцать лет -- измерены, не назначены. */
export const FLOOR_FOM = 32;
export const PEAK_FOM = 70;

/** Норма корзины: медиана её объёма по всему ряду. */
export const BASKET_NORMAL: Record<BasketKey, number> = {"рамка":72,"выживание":80,"конец света":436,"вера":310};

export const BASKET_KEYS: BasketKey[] = ["рамка", "выживание", "конец света", "вера"];
export const MOB_DATE = "2022-09-19";

/** Обычная неделя: медиана индекса по всему ряду. */
export const BASELINE = (() => {
  const s = SERIES.map((w) => w.idx).sort((a, b) => a - b);
  return Math.round(s[s.length >> 1] * 10) / 10;
})();

/**
 * ГРАНИЦА ЭПОХ. До 2020 года прибор короче: ось укрытия (Tor) применяется
 * только с 2020-го и меняет значения 312 недель из 519, не трогая ни одной
 * ранней. Ранние недели она не судит вовсе -- они стоят на месте, пока
 * поздние перераспределяются, и всплывают наверх сами собой. Измерено: до
 * осей ранних недель в верхней двадцатке 0, после осей -- 10 из 20, при их
 * доле в ряду 36.6 %.
 *
 * Поэтому недели по разные стороны границы НЕ СРАВНИВАЮТСЯ рангом.
 * Значения оставлены как есть: меняется не прибор, а то, что мы вправе
 * утверждать.
 */
export const ГРАНИЦА_ЭПОХ = "2020-01-01";
export const РАННЯЯ = SERIES.filter((w) => w.date < ГРАНИЦА_ЭПОХ);
export const ПОЗДНЯЯ = SERIES.filter((w) => w.date >= ГРАНИЦА_ЭПОХ);

/** Пик СВОЕЙ эпохи: между эпохами пики не сравниваются. */
export function пикЭпохи(date: string): Week {
  const свои = date < ГРАНИЦА_ЭПОХ ? РАННЯЯ : ПОЗДНЯЯ;
  return свои.reduce((a, b) => (b.idx > a.idx ? b : a));
}

/** Место недели внутри СВОЕЙ эпохи, а не среди всех 519. */
export function местоВЭпохе(date: string): { место: number; всего: number } {
  const свои = date < ГРАНИЦА_ЭПОХ ? РАННЯЯ : ПОЗДНЯЯ;
  const я = свои.find((w) => w.date === date);
  if (!я) return { место: 0, всего: свои.length };
  return { место: свои.filter((w) => w.idx > я.idx).length + 1, всего: свои.length };
}

export const PEAK = SERIES.reduce((a, b) => (b.idx > a.idx ? b : a));
export const LATEST = SERIES[SERIES.length - 1];
export const MOB_INDEX = SERIES.findIndex((w) => w.date === MOB_DATE);

export function indexOfDate(d: string): number {
  let lo = 0, hi = SERIES.length - 1, best = 0;
  while (lo <= hi) {
    const m = (lo + hi) >> 1;
    if (SERIES[m].date <= d) { best = m; lo = m + 1; } else hi = m - 1;
  }
  return best;
}
